{"code":"def generate(rng):
    h=rng.randint(3,10)
    w=rng.randint(3,10)
    # Varied ARC-style grids with a dominant background and sparse colored objects.
    bg=rng.choice([0,0,0,1])
    colors=[c for c in range(1,10) if c!=bg]
    grid=[[bg for _ in range(w)] for _ in range(h)]
    for _ in range(rng.randint(1,max(1,(h*w)//3))):
        r=rng.randrange(h); c=rng.randrange(w)
        grid[r][c]=rng.choice(colors)
        if rng.random()<0.35:
            for dr,dc in [(1,0),(0,1),(-1,0),(0,-1)]:
                rr=r+dr; cc=c+dc
                if 0<=rr<h and 0<=cc<w and rng.random()<0.5:
                    grid[rr][cc]=grid[r][c]
    return grid"}

